# <><><><><> API <><><><><>#
def send_hello_request(logger, address, timeout=1, max_timeout=3):
    # type: (Logger, str, Num, Num) -> Dict[str, Any]
    """
    Send hello request to the specified address.
    If it fails within max_timeout, recovery action can be executed.
    :param logger: network logger
    :param address: IP address where to send message
    :param timeout: time within remote address should respond to the message. It can be retried within max_timeout
    :param max_timeout: maximum time within remote address should respond to the message
    :return: Received answer for message that was send
    """
    recovery = False
    return _send_message_and_recover_factory(
        logger, deepcopy(req_hello), address, timeout, max_timeout, recovery=recovery
    )


def send_start_request(
    logger,
    address,
    timeout=DEF_ALL_PLUGS_START_TIMEOUT,
    max_timeout=DEF_ALL_PLUGS_START_TIMEOUT,
    recovery=True,
    **kwargs
):
    # type: (Logger, str, Num, Num, bool, Optional[Dict[str, Any]]) -> Dict[str, Any]
    """
    Sends start request to the specified address.
    If it fails within max_timeout, recovery action can be executed.
    :param logger: network logger
    :param address: IP address where to send message
    :param timeout: time within remote address should respond to the message. It can be retried within max_timeout
    :param max_timeout: maximum time within remote address should respond to the message
    :param recovery: Flag whether recovery action should be executed or not
    :return: Received answer for message that was send
    """
    req_start_copied = _get_request_with_adds(deepcopy(req_start), kwargs.get("msg_adds", {}))
    recovery_func = partial(_start_recovery, logger, address, **kwargs)
    return _send_message_and_recover_factory(
        logger, req_start_copied, address, timeout, max_timeout, recovery_func, recovery
    )


