def send_get_state_request(logger, address, timeout=1, max_timeout=MAX_GET_STATE_TIMEOUT):
    # type: (Logger, str, Num, Num) -> Union[StatusCode, RunnerStates]
    """
    Sends get_state request to the specified address.
    If it fails within max_timeout, recovery action can be executed.
    :param logger: network logger
    :param address: IP address where to send message
    :param timeout: time within remote address should respond to the message. It can be retried within max_timeout
    :param max_timeout: maximum time within remote address should respond to the message
    :return: Received answer for message that was sent
    """
    data = _send_message_and_recover_factory(
        logger, deepcopy(req_get_state), address, timeout, max_timeout, recovery=False
    )
    try:
        return data["state"]
    except Exception as err:
        logger.debug(err, exc_info=True)
        return StatusCode.NoConnection


