# <><><><><> INTERNAL <><><><><>#
def _send_message_and_recover_factory(
    logger, request, address, timeout, max_timeout, recovery_func=None, recovery=True
):
    # type: (Logger, Dict[str, Any], str, Num, Num, Optional[Callable], bool) -> Dict[str, Any]
    """Factory method for handling sending message and recovery actions. Should never be called by itself."""
    logger.debug(REQ_PREPARE_TEMPLATE.substitute(address=address, port=SERVER_PORT, request=request, timeout=timeout))
    _start_time = time.time()
    while (time.time() - _start_time) < max_timeout:
        time_left = max_timeout - (time.time() - _start_time)
        _timeout = timeout if timeout < time_left else time_left
        try:
            response = client(message=request, host=address, port=SERVER_PORT, socket_timeout=_timeout)
            if response["status"] != StatusCode.OK:
                logger.error(
                    ERROR_TEMPLATE.substitute(
                        address=address,
                        port=SERVER_PORT,
                        request=request,
                        error=response["status"],
                    )
                )
            else:
                logger.debug(
                    RESPONSE_TEMPLATE.substitute(
                        address=address,
                        port=SERVER_PORT,
                        request=pformat(request),
                        response=response,
                    )
                )
            return response
        except (gaierror, socket_timeout, socket_error) as err:
            err_msg = str(err)
            # todo fix this error - it's not this type :)
            if not issubclass(type(err), OSError):
                err_msg += ". Other side socket is probably closed."
            logger.debug(ERROR_TEMPLATE.substitute(address=address, port=SERVER_PORT, request=request, error=err_msg))
            time.sleep(1)
    if recovery and callable(recovery_func):
        _recovery_resp = recovery_func()
        if _recovery_resp:
            logger.debug(RECOVERY_OK_TEMPLATE.substitute(address=address, port=SERVER_PORT, request=request))
            logger.debug(
                RESPONSE_TEMPLATE.substitute(
                    address=address,
                    port=SERVER_PORT,
                    request=request,
                    response=_recovery_resp,
                )
            )
            return _recovery_resp
        else:
            logger.debug(RECOVERY_NOK_TEMPLATE.substitute(address=address, port=SERVER_PORT, request=request))
    return {
        "reply": request["action"],
        "status": StatusCode.ServerError,
        "state": "UNKNOWN",
    }


