def _get_request_with_adds(request, additions):
    # type: (Dict[str, Any], Dict[str, Any]) -> Dict[str, Any]
    """Creates copy of general request dict and updates it with additional records"""
    request_copied = deepcopy(request)
    request_copied.update(additions)
    return request_copied


# <><><><><> INTERNAL - recovery <><><><><>#
def _start_recovery(logger, address, **kwargs):
    # type: (Logger, str, Optional[Dict[str, Any]]) -> Union[Dict[str, Any], bool]
    """
    Recovery method for 'send_start_request'.
    If server is still starting it will wait up to 60s to let it finish
    If server has already started it will return True
    If server did not start it tries to start it again.
    :param logger: network logger
    :param address: IP address where to send message
    :return: Dictionary with response or bool whether recovery was successful or not
    """
    start_time = time.time()
    while (time.time() - start_time) < 60:
        state = send_get_state_request(logger, address)
        if state == RunnerStates.STARTING:
            time.sleep(1)
        elif state == RunnerStates.STARTED:
            return {"reply": "start", "status": StatusCode.OK, "state": state}
        elif state in (RunnerStates.READY, RunnerStates.COMPRESSING):
            return send_start_request(logger, address, recovery=False, **kwargs)
    return {"reply": "start", "status": StatusCode.ServerError, "state": "UNKNOWN"}


def _stop_recovery(logger, address, **kwargs):
    # type: (Logger, str, Optional[Dict[str, Any]]) -> Union[Dict[str, Any], bool]
    """
    Recovery method for 'send_stop_request'.
    If server is still stopping it will wait up to 5*60s to let it finish
    If server has already stopped it will return True
    If server did not start finishing it tries to stop it again.
    :param logger: network logger
    :param address: IP address where to send message
    :return: Dictionary with response or bool whether recovery was successful or not
    """
    start_time = time.time()
    while (time.time() - start_time) < DEF_ALL_PLUGS_STOP_TIMEOUT:
        state = send_get_state_request(logger, address)
        if state == RunnerStates.STOPPING:
            time.sleep(1)
        elif state in (
            RunnerStates.STOPPED,
            RunnerStates.COMPRESSING,
            RunnerStates.READY,
        ):
            return {"reply": "stop", "status": StatusCode.OK, "state": state}
        elif state == RunnerStates.STARTED:
            return send_stop_request(logger, address, recovery=False, **kwargs)
    return {"reply": "stop", "status": StatusCode.ServerError, "state": "UNKNOWN"}


def _compress_logs_recovery(logger, address, **kwargs):
    # type: (Logger, str, Optional[Dict[str, Any]]) -> Union[Dict[str, Any], bool]
    """
    Recovery method for 'send_compress_logs_request'.
    If server is still compressing it will wait up to MAX_COMPRESSION_TIME to let it finish
    If server has already compressed it will ask for logs location.
    If server did not start compressing it tries to get logs compressed again.
    :param logger: network logger
    :param address: IP address where to send message
    :return: Dictionary with response or bool whether recovery was successful or not
    """
    start_time = time.time()
    while (time.time() - start_time) < MAX_COMPRESSION_TIME:
        state = send_get_state_request(logger, address)
        if state in (RunnerStates.COMPRESSING, RunnerStates.STOPPING):
            time.sleep(1)
        elif state == RunnerStates.READY:
            logs_location = _send_get_logs_location(logger, address)["logs_location"]
            return {
                "reply": "compress",
                "status": StatusCode.OK,
                "state": state,
                "logs_location": logs_location,
            }
        elif state == RunnerStates.STOPPED:
            return send_compress_logs_request(logger, address, recovery=False, **kwargs)
    return {
        "reply": "compress",
        "status": StatusCode.ServerError,
        "state": "UNKNOWN",
        "logs_location": None,
    }


